-- Generated by esquadro: an app's user and database, created once, with its
-- password kept up to date. :app and :password are set before.
SELECT format('CREATE ROLE %I LOGIN', :'app') WHERE NOT EXISTS (SELECT FROM pg_roles WHERE rolname = :'app') \gexec
SELECT 'created' WHERE NOT EXISTS (SELECT FROM pg_database WHERE datname = :'app');
SELECT format('ALTER ROLE %I WITH LOGIN PASSWORD %L', :'app', :'password') \gexec
SELECT format('CREATE DATABASE %I OWNER %I', :'app', :'app') WHERE NOT EXISTS (SELECT FROM pg_database WHERE datname = :'app') \gexec
SELECT format('REVOKE ALL ON DATABASE %I FROM PUBLIC', :'app') \gexec
-- No app reaches PostgreSQL's own database either.
REVOKE CONNECT ON DATABASE postgres FROM PUBLIC;
